import{_ as s,o as a,c as n,ae as i}from"./chunks/framework.CkRokae0.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"sessions/04-adr/how-to-use.md","filePath":"sessions/04-adr/how-to-use.md"}'),l={name:"sessions/04-adr/how-to-use.md"};function e(o,t,r,d,h,p){return a(),n("div",null,[...t[0]||(t[0]=[i(`<h2 id="要約" tabindex="-1">要約 <a class="header-anchor" href="#要約" aria-label="Permalink to &quot;要約&quot;">​</a></h2><p>ADR を無理なく運用するには、段階的に始めることが大切です。個人 → 小チーム → 全体組織という流れで徐々に広げるのが現実的です。</p><h2 id="いつ書くか" tabindex="-1">いつ書くか <a class="header-anchor" href="#いつ書くか" aria-label="Permalink to &quot;いつ書くか&quot;">​</a></h2><ul><li><strong>迷ったとき</strong>：複数の選択肢があり、トレードオフを感じるとき</li><li><strong>質問されそうなとき</strong>：「なぜこうしたの？」と後で聞かれそうな重要な判断</li><li><strong>長期影響があるとき</strong>：半年以上の間、影響し続ける判断</li><li><strong>前提が複雑なとき</strong>：理由が自明でなく、背景説明が必要なとき</li></ul><p>逆に「いつも書く」というルールは避けましょう。書く価値がない小さい判断まで記録すると、ドキュメント負荷が増えて運用が続きません。</p><h2 id="どの粒度で書くか" tabindex="-1">どの粒度で書くか <a class="header-anchor" href="#どの粒度で書くか" aria-label="Permalink to &quot;どの粒度で書くか&quot;">​</a></h2><ul><li><p><strong>目安：5～10分で書ける程度</strong></p><ul><li>背景は「要件・制約」に限定（全部は書かない）</li><li>決定は1～2行（選んだ案と理由）</li><li>帰結は「影響と注意点」に限定</li></ul></li><li><p><strong>構成例</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Context: 3～5行</span></span>
<span class="line"><span>Decision: 1～2行</span></span>
<span class="line"><span>Consequences: 3～5行</span></span>
<span class="line"><span>計10～12行程度が目安</span></span></code></pre></div></li><li><p><strong>詳細は別置き</strong></p><ul><li>実装詳細や設計図は ADR に書かず、別ファイルにリンク</li><li>ADR は「判断の理由」に集中</li></ul></li></ul><h2 id="段階別運用パターン" tabindex="-1">段階別運用パターン <a class="header-anchor" href="#段階別運用パターン" aria-label="Permalink to &quot;段階別運用パターン&quot;">​</a></h2><p><strong>推奨進行フロー</strong></p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">timeline</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    title ADR 運用の段階的導入（目安期間）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    section 段階1</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        最初の1～2ヶ月 : 個人で始める : 迷った判断を記録 : 目安1～2件/月</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    section 段階2</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        2～3ヶ月目以降 : 小チームで拡張 : チーム判断を共有 : PR+レビュー活用</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    section 段階3</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        4ヶ月以降 : 組織全体（プロセス化） : 年1回見直し : 学習文化化</span></span></code></pre></div><p><strong>段階別スコープ比較</strong></p><table tabindex="0"><thead><tr><th>項目</th><th>段階1（個人）</th><th>段階2（小チーム）</th><th>段階3（組織全体）</th></tr></thead><tbody><tr><td><strong>対象</strong></td><td>個人が迷った重要判断</td><td>チーム全体に影響する重要判断</td><td>会社全体で参考になる判断</td></tr><tr><td><strong>フォーマット</strong></td><td>自由（完璧さ不要）</td><td>テンプレ化（Context/Decision/Consequences）</td><td>テンプレ化 + ガバナンス</td></tr><tr><td><strong>命名・管理</strong></td><td>自由</td><td>ADR-001, ADR-002 のように番号化</td><td>番号化 + 分類</td></tr><tr><td><strong>共有方法</strong></td><td>チーム内フォルダ</td><td>PR に添える、レビュー時に説明</td><td>組織共有システム + アーカイブ</td></tr><tr><td><strong>更新頻度</strong></td><td>判断が出たときだけ</td><td>同上</td><td>年1～2回見直し</td></tr><tr><td><strong>承認プロセス</strong></td><td>なし</td><td>簡易レビュー（強制でない）</td><td>軽量レビュー（ガバナンス化しない）</td></tr></tbody></table><h3 id="段階1-個人で始める-最初の1-2ヶ月" tabindex="-1">段階1：個人で始める（最初の1～2ヶ月） <a class="header-anchor" href="#段階1-個人で始める-最初の1-2ヶ月" aria-label="Permalink to &quot;段階1：個人で始める（最初の1～2ヶ月）&quot;">​</a></h3><ul><li><strong>対象</strong>：個人が迷った重要な判断だけ</li><li><strong>フォーマット</strong>：自由（完璧さは不要）</li><li><strong>保存</strong>：チームのドキュメントフォルダに ADR フォルダを作成</li><li><strong>目標</strong>：1ヶ月に1～2件書いてみる</li><li><strong>例</strong>：「キャッシュ戦略をどうするか迷った → ADR に残す」</li></ul><h3 id="段階2-小チーム-チーム内共有-で拡張-2-3ヶ月目以降" tabindex="-1">段階2：小チーム（チーム内共有）で拡張（2～3ヶ月目以降） <a class="header-anchor" href="#段階2-小チーム-チーム内共有-で拡張-2-3ヶ月目以降" aria-label="Permalink to &quot;段階2：小チーム（チーム内共有）で拡張（2～3ヶ月目以降）&quot;">​</a></h3><ul><li><strong>対象</strong>：チーム全体に影響する重要な判断</li><li><strong>形式</strong>：簡単なテンプレを決める（Context/Decision/Consequences）</li><li><strong>共有</strong>：PR に ADR ファイルを添える（レビュー時に背景を共有）</li><li><strong>命名</strong>：ADR-001-xxx.md と番号を振る</li><li><strong>頻度</strong>：重要度高い判断が出たときだけ（強制しない）</li><li><strong>例</strong>：「DB を PostgreSQL にするか MongoDB にするか → チーム内で ADR として共有」</li></ul><h3 id="段階3-組織全体-プロセス化" tabindex="-1">段階3：組織全体（プロセス化） <a class="header-anchor" href="#段階3-組織全体-プロセス化" aria-label="Permalink to &quot;段階3：組織全体（プロセス化）&quot;">​</a></h3><ul><li><strong>対象</strong>：会社全体で参考になる判断</li><li><strong>ガバナンス</strong>：重要度に応じた簡易レビュー（強制ではなく）</li><li><strong>アーカイブ</strong>：年1回、「この ADR の前提は今も有効か」を見直し</li><li><strong>学習</strong>：新しいプロジェクトで過去 ADR を参考にする文化</li></ul><p><strong>重要な注意</strong>：段階3 に急に進むと「完璧な記述」「承認フロー」化して、書く人の負担が増え、続きません。段階2 程度で十分という企業も多いです。焦らず、チームの実感に合わせて進めることが成功のコツです。</p><h2 id="書き方と運用のコツ" tabindex="-1">書き方と運用のコツ <a class="header-anchor" href="#書き方と運用のコツ" aria-label="Permalink to &quot;書き方と運用のコツ&quot;">​</a></h2><h3 id="背景-context-を書くコツ" tabindex="-1">背景（Context）を書くコツ <a class="header-anchor" href="#背景-context-を書くコツ" aria-label="Permalink to &quot;背景（Context）を書くコツ&quot;">​</a></h3><ul><li>要件・制約に限定（「どうやるか」は書かない）</li><li>比較対象を明記（何と比較したか）</li><li>当時のチーム規模やスキルレベルを簡潔に</li></ul><h3 id="決定-decision-を書くコツ" tabindex="-1">決定（Decision）を書くコツ <a class="header-anchor" href="#決定-decision-を書くコツ" aria-label="Permalink to &quot;決定（Decision）を書くコツ&quot;">​</a></h3><ul><li>選んだ案だけを明確に</li><li>簡潔な理由を1～2行で（詳細は Consequences で）</li></ul><h3 id="帰結-consequences-を書くコツ" tabindex="-1">帰結（Consequences）を書くコツ <a class="header-anchor" href="#帰結-consequences-を書くコツ" aria-label="Permalink to &quot;帰結（Consequences）を書くコツ&quot;">​</a></h3><ul><li>メリット（期待される効果）</li><li>デメリット（注意すべき点、リスク）</li><li>次のステップ（設定値、導入方法など）</li></ul><h3 id="運用パターン例" tabindex="-1">運用パターン例 <a class="header-anchor" href="#運用パターン例" aria-label="Permalink to &quot;運用パターン例&quot;">​</a></h3><ul><li><strong>PR に ADR を添える</strong>：「DB 選定 PR に ADR-001 を添えてレビュー」</li><li><strong>リファクタ時に参照</strong>：「古い設計を変更する前に ADR を確認」</li><li><strong>新プロジェクト開始時</strong>：「過去 ADR を参考に同じ判断は必要か確認」</li></ul><hr><h2 id="ナビゲーション" tabindex="-1">ナビゲーション <a class="header-anchor" href="#ナビゲーション" aria-label="Permalink to &quot;ナビゲーション&quot;">​</a></h2><p><a href="./why-adr.html">← 前へ: なぜ使うか</a> · <a href="./template.html">次へ: テンプレート →</a> · <a href="./">ADRトップへ</a></p>`,31)])])}const u=s(l,[["render",e]]);export{c as __pageData,u as default};
